patches.diff:
From 24f267cb595d44c6a127e118bad1342a193b563d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:14:01 +0100
Subject: [PATCH] desktoppackage: keep the old desktop until the new wallpaper
 has loaded

The old activity's desktop was hidden before the new one had slid in and
loaded its wallpaper, so switching showed black, for over a second on a
first switch to a large image. Keep it under the new one until then.

BUG: 476406
---
 desktoppackage/contents/views/Desktop.qml | 30 ++++++++++++++++++++---
 1 file changed, 26 insertions(+), 4 deletions(-)

diff --git a/desktoppackage/contents/views/Desktop.qml b/desktoppackage/contents/views/Desktop.qml
index 1be09364ef..85ee852234 100644
--- a/desktoppackage/contents/views/Desktop.qml
+++ b/desktoppackage/contents/views/Desktop.qml
@@ -311,6 +311,13 @@ Item {

         containment.parent = containmentParent

+        if (internal.leavingContainment) {
+            if (internal.leavingContainment !== containment) {
+                internal.leavingContainment.visible = false;
+            }
+            internal.leavingContainment = null;
+        }
+
         if (switchAnim.running) {
             //If the animation was still running, stop it and reset
             //everything so that a consistent state can be kept
@@ -343,6 +350,17 @@ Item {

         property Item oldContainment: null
         property Item newContainment: null
+        // Kept visible under the new containment until its wallpaper has loaded
+        property Item leavingContainment: null
+        property real oldContainmentX: 0
+
+        readonly property bool wallpaperLoading: root.containment?.wallpaper?.loading ?? false
+        onWallpaperLoadingChanged: {
+            if (!wallpaperLoading && leavingContainment) {
+                leavingContainment.visible = false;
+                leavingContainment = null;
+            }
+        }
     }

     SequentialAnimation {
@@ -355,14 +373,16 @@ Item {
                 }
                 if (internal.oldContainment) {
                     internal.oldContainment.z = 0;
-                    internal.oldContainment.x = 0;
+                    internal.oldContainmentX = 0;
+                    internal.oldContainment.x = Qt.binding(() => internal.wallpaperLoading ? 0 : internal.oldContainmentX);
+                    internal.oldContainment.visible = true;
                 }
             }
         }
         ParallelAnimation {
             NumberAnimation {
-                target: internal.oldContainment
-                properties: "x"
+                target: internal
+                properties: "oldContainmentX"
                 to: internal.newContainment != null ? -root.width : 0
                 duration: Kirigami.Units.veryLongDuration
                 easing.type: Easing.InOutQuad
@@ -377,7 +397,9 @@ Item {
         }
         ScriptAction {
             script: {
-                if (internal.oldContainment) {
+                if (internal.wallpaperLoading) {
+                    internal.leavingContainment = internal.oldContainment;
+                } else if (internal.oldContainment) {
                     internal.oldContainment.visible = false;
                 }
                 if (containment) {
-- 
2.53.0

